import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
import {setLogger} from '../../shared/logger.js';

function definition(inputSchema: Record<string, unknown>): ToolDefinition {
  return {name: 'weather', description: 'Get a forecast', inputSchema};
}

function observedSchema(required: string[]) {
  let reads = 0;
  const schema = {
    type: 'object',
    required,
    get properties() {
      reads++;
      return {location: {type: 'string'}, postcode: {type: 'string'}};
    },
  };
  return {schema, readCount: () => reads};
}

// @spec specs/hal-engine-tool-input-validation/spec.md#1
it('rejects malformed tool input privately and preserves accepted arguments', async () => {
  const registry = new ToolRegistry();
  const executed: Record<string, unknown>[] = [];
  const lines: string[] = [];
  const write = (category: string, message: string, fields?: Record<string, unknown>) => {
    lines.push(JSON.stringify({category, message, fields}));
  };
  setLogger({debug: write, info: write, warn: write, error: write});
  try {
    registry.register(
      definition({
        type: 'object',
        required: ['location'],
        properties: {
          location: {type: 'string'},
          units: {type: 'string', enum: ['metric', 'imperial'], default: 'metric'},
          contact: {type: 'object', properties: {name: {type: 'string'}}},
        },
      }),
      async input => {
        executed.push(structuredClone(input));
        return 'forecast';
      }
    );
    const cases = [
      {input: {}, path: /location/i, constraint: /required/i, secret: '[REDACTED_SECRET]'},
      {input: {location: 987654321}, path: /location/i, constraint: /string/i, secret: '[REDACTED_SECRET]'},
      {input: {location: 'Paris', units: 'private-unit'}, path: /units/i, constraint: /enum/i, secret: '[REDACTED_SECRET]'},
      {
        input: {location: 'Paris', contact: {name: 123456789}},
        path: /contact.*name/i,
        constraint: /string/i,
        secret: '[REDACTED_SECRET]',
      },
    ];
    const rejected = [];
    for (const entry of cases) {
      const input = {...entry.input, identifying: 'private@example.test'};
      const before = structuredClone(input);
      const start = lines.length;
      const response = await registry.execute('weather', input);
      const logs = lines.slice(start).join('\\n');
      rejected.push({
        path: entry.path.test(response.result),
        constraint: entry.constraint.test(response.result),
        loggedPath: entry.path.test(logs),
        loggedConstraint: entry.constraint.test(logs),
        leaksValue: [entry.secret, 'private@example.test'].some(value => (response.result + logs).includes(value)),
        unchanged: JSON.stringify(input) === JSON.stringify(before),
      });
    }
    const invalidExecutions = executed.length;
    const accepted = {location: 'Paris', unlisted: {postalCode: '00123'}};
    const response = await registry.execute('weather', accepted);
    const unknown = await registry.execute('missing', {}).then(
      () => 'did not throw',
      (error: Error) => error.message
    );
    expect({rejected, invalidExecutions, acceptedExecutions: executed.slice(invalidExecutions), response, unknown}).toEqual({
      rejected: cases.map(() => ({
        path: true,
        constraint: true,
        loggedPath: true,
        loggedConstraint: true,
        leaksValue: false,
        unchanged: true,
      })),
      invalidExecutions: 0,
      acceptedExecutions: [{location: 'Paris', unlisted: {postalCode: '00123'}}],
      response: {result: 'forecast'},
      unknown: 'Unknown tool: missing',
    });
  } finally {
    setLogger();
  }
});

// @spec specs/hal-engine-tool-input-validation/spec.md#2
it('compiles static schemas at registration and reuses validation for ten calls', async () => {
  const registry = new ToolRegistry();
  let registrationError = '';
  try {
    registry.register(definition({type: 'not-a-json-schema-type'}), async () => 'forecast');
  } catch (error) {
    registrationError = String(error);
  }
  const observed = observedSchema(['location']);
  registry.register(definition(observed.schema), async () => 'forecast');
  const readsAtRegistration = observed.readCount();
  const results = [];
  for (let i = 0; i < 10; i++) results.push(await registry.execute('weather', {location: 'Paris'}));
  expect({
    errorNamesTool: registrationError.includes('weather'),
    schemaReadAtRegistration: readsAtRegistration > 0,
    schemaReadsDuringExecution: observed.readCount() - readsAtRegistration,
    results,
  }).toEqual({
    errorNamesTool: true,
    schemaReadAtRegistration: true,
    schemaReadsDuringExecution: 0,
    results: Array.from({length: 10}, () => ({result: 'forecast'})),
  });
});

// @spec specs/hal-engine-tool-input-validation/spec.md#3
it('validates each dynamic definition and reuses only the same schema object', async () => {
  const registry = new ToolRegistry();
  const location = observedSchema(['location']);
  const postcode = observedSchema(['postcode']);
  let current = location;
  const executed: Record<string, unknown>[] = [];
  registry.register(
    () => definition(current.schema),
    async input => {
      executed.push(input);
      return 'forecast';
    }
  );
  await registry.execute('weather', {location: 'Paris'});
  const locationReads = location.readCount();
  current = postcode;
  const rejection = await registry.execute('weather', {location: 'Paris'});
  await registry.execute('weather', {postcode: '75001'});
  const postcodeReads = postcode.readCount();
  current = location;
  await registry.execute('weather', {location: 'Berlin'});
  current = postcode;
  await registry.execute('weather', {postcode: '10115'});
  expect({
    rejectionNamesCurrentRequirement: /postcode/i.test(rejection.result) && /required/i.test(rejection.result),
    bothSchemasCompiled: locationReads > 0 && postcodeReads > 0,
    locationReused: location.readCount() === locationReads,
    postcodeReused: postcode.readCount() === postcodeReads,
    executed,
  }).toEqual({
    rejectionNamesCurrentRequirement: true,
    bothSchemasCompiled: true,
    locationReused: true,
    postcodeReused: true,
    executed: [{location: 'Paris'}, {postcode: '75001'}, {location: 'Berlin'}, {postcode: '10115'}],
  });
});
EOF
